<?php if($report['status']==='pending'): ?><section class="actions"><form method="post" action="<?= e(app_url('/admin/payments/manual/review')) ?>"><?= csrf_field() ?><input type="hidden" name="report_id" value="<?= (int)$report['id'] ?>"><label class="muted" for="review-note-<?= (int)$report['id'] ?>"><?= e(villa_ui('Yönetici notu (isteğe bağlı)')) ?></label><textarea id="review-note-<?= (int)$report['id'] ?>" name="review_note" maxlength="1000" placeholder="Dekont / banka kontrol notu"></textarea><div class="action-row"><button type="submit" name="decision" value="approved"><?= e(villa_ui('Ödemeyi onayla')) ?></button><button class="reject" type="submit" name="decision" value="rejected"><?= e(villa_ui('Bildirimi reddet')) ?></button></div></form></section><?php else: ?><section class="details"><div><strong><?= e(villa_ui('İşlemi yapan:')) ?></strong> <?= e($report['reviewer_name']??villa_ui('Yönetici')) ?></div><div><strong><?= e(villa_ui('İşlem zamanı:')) ?></strong> <?= e($report['reviewed_at']?date('d.m.Y H:i',strtotime($report['reviewed_at'])):'—') ?></div></section><?php endif; ?></article><?php endforeach; ?>
