<section aria-label="Bank refunds"><h2><?= e(villa_ui('Banka iadesi kayıtları')) ?></h2><p class="muted"><?= e(villa_ui('Bu kayıtlar banka iadesinin takip durumunu gösterir. Banka dekontu doğrulanmadan ödeme tamamlandı kabul edilmez.')) ?></p>
<?php foreach(($bankRefunds??[]) as $refund): ?><article class="report"><section><h2><?= e($refund['property_title']) ?></h2><div class="muted"><?= e(villa_ui('Rezervasyon:')) ?> <?= e($refund['booking_code']) ?></div><div class="muted"><?= e(date('d.m.Y H:i',strtotime($refund['created_at']))) ?></div></section><section class="details"><div class="amount"><?= e(number_format((float)$refund['amount'],2,',','.')) ?> <?= e($refund['currency']) ?></div><div><strong><?= e(villa_ui('Durum:')) ?></strong> <?= e(['pending'=>'Beklemede','processing'=>villa_ui('İşleniyor'),'succeeded'=>villa_ui('Tamamlandı'),'failed'=>villa_ui('Başarısız'),'cancelled'=>villa_ui('İptal')][$refund['status']]??$refund['status']) ?></div><div><strong><?= e(villa_ui('Banka referansı:')) ?></strong> <?= e($refund['bank_reference']??'—') ?></div></section><section class="details"><div><strong><?= e(villa_ui('Gerekçe:')) ?></strong> <?= e($refund['reason']??'—') ?></div><div><strong><?= e(villa_ui('İnceleyen:')) ?></strong> <?= e($refund['reviewer_name']) ?></div><div><strong><?= e(villa_ui('Tamamlanma:')) ?></strong> <?= e($refund['completed_at']?date('d.m.Y H:i',strtotime($refund['completed_at'])):'—') ?></div></section><?php if(in_array($refund['status'],['pending','processing'],true)): ?><section class="actions"><form method="post" action="<?= e(app_url('/admin/payments/manual/refunds/review')) ?>"><?= csrf_field() ?><input type="hidden" name="refund_id" value="<?= (int)$refund['id'] ?>"><label for="refund-ref-<?= (int)$refund['id'] ?>"><?= e(villa_ui('Banka referansı (isteğe bağlı)')) ?></label><input id="refund-ref-<?= (int)$refund['id'] ?>" name="bank_reference" maxlength="190" value="<?= e($refund['bank_reference']??'') ?>" style="width:100%;padding:10px;margin:6px 0 12px"><div class="action-row"><?php if($refund['status']==='pending'): ?><button type="submit" name="decision" value="processing"><?= e(villa_ui('İşleme al')) ?></button><?php endif; ?><button class="reject" type="submit" name="decision" value="failed"><?= e(villa_ui('Başarısız')) ?></button><button type="submit" name="decision" value="cancelled"><?= e(villa_ui('İptal et')) ?></button></div></form></section><?php endif; ?><?php if($refund['status']==='processing'): ?><section class="actions"><form method="post" action="<?= e(app_url('/admin/payments/manual/refunds/settle')) ?>"><?= csrf_field() ?><input type="hidden" name="refund_id" value="<?= (int)$refund['id'] ?>"><label for="settlement-ref-<?= (int)$refund['id'] ?>"><?= e(villa_ui('Banka dekont / işlem referansı')) ?></label><input id="settlement-ref-<?= (int)$refund['id'] ?>" name="bank_reference" maxlength="190" required value="<?= e($refund['bank_reference']??'') ?>" style="width:100%;padding:10px;margin:6px 0 12px"><label><input type="checkbox" name="bank_transfer_verified" value="1" required> <?= e(villa_ui('Banka hesabında iadenin gerçekten gerçekleştiğini doğruladım.')) ?></label><p class="muted"><?= e(villa_ui('Bu onay finans kayıtlarını günceller; bankaya yeni transfer göndermez.')) ?></p><button type="submit"><?= e(villa_ui('Doğrulanmış iadeyi tamamla')) ?></button></form></section><?php endif; ?></article><?php endforeach; ?>
